function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(
    source.rawText || source.text || message.text || message.caption || payload.text || ''
  ).trim();
  return { payload, message, chatId, rawText };
}

function cleanQuery(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const text = normalize(raw);
const prefixes = ['tim doc', 'search doc', 'tim tai lieu'];
let body = raw;
for (const prefix of prefixes) {
  if (text.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

const query = cleanQuery(
  source.query ||
  source.docName ||
  source.targetName ||
  source.fileName ||
  args.query ||
  args.docName ||
  args.targetName ||
  ctx.payload.query ||
  ctx.payload.docName ||
  body
);
const limit = Number(source.limit || args.limit || source.payload?.limit || 5) || 5;
const folderId = String(source.folderId || args.folderId || source.payload?.folderId || '').trim();

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text,
    query,
    docName: query,
    targetName: cleanQuery(source.targetName || args.targetName || query),
    folderId,
    limit,
    hasTarget: Boolean(query),
    response: query ? '' : '📝 <b>Tim Google Doc</b>\n\nVi du: <code>tim doc Project Plan</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name).slice(0, 3);
const query = source.query || '';

let text = '';
if (!rows.length) {
  text = query
    ? `Mia chưa thấy tài liệu nào thật sự khớp với từ khóa "${query}".`
    : 'Mia chưa tìm thấy tài liệu phù hợp.';
} else {
  text = query
    ? `Mia tìm thấy ${rows.length} tài liệu khá khớp với từ khóa "${query}":`
    : `Mia tìm thấy ${rows.length} tài liệu phù hợp:`;
  const links = [];
  rows.forEach((doc, index) => {
    const name = doc.name || 'Không rõ tên';
    const link = doc.webViewLink || (doc.id ? `https://docs.google.com/document/d/${doc.id}/edit` : '');
    const modified = doc.modifiedTime ? new Date(doc.modifiedTime).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }) : '';
    text += `\n${index + 1}. ${name}`;
    if (modified) text += ` — sửa lúc ${modified}`;
    if (link) links.push(link);
  });
  if (links.length) {
    text += '\n\nMở tài liệu:';
    links.slice(0, 3).forEach((link, index) => {
      text += `\n${index + 1}. ${link}`;
    });
  }
}

return [{ json: { chatId: source.chatId, text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
